// Bloom Filter — O(k) insert and query, O(m) space
class BloomFilter {
  #bits;  // Uint8Array — 1 byte per slot, but treated as bit array
  #m;     // number of bits
  #k;     // number of hash functions

  constructor(m = 1024, k = 7) {
    this.#m    = m;
    this.#k    = k;
    this.#bits = new Uint8Array(Math.ceil(m / 8));
  }

  // Simple double-hashing to generate k independent positions
  // In production use MurmurHash3 or FNV variants
  #positions(item) {
    const s   = String(item);
    let   h1  = 0, h2 = 0;
    for (let i = 0; i < s.length; i++) {
      const c = s.charCodeAt(i);
      h1 = Math.imul(31, h1) + c | 0;
      h2 = Math.imul(37, h2) + c | 0;
    }
    const positions = [];
    for (let i = 0; i < this.#k; i++) {
      // Double hashing: gi(x) = (h1 + i*h2) mod m
      const pos = ((h1 + i * h2) % this.#m + this.#m) % this.#m;
      positions.push(pos);
    }
    return positions;
  }

  #setBit(pos)    { this.#bits[pos >> 3] |=  (1 << (pos & 7)); }
  #testBit(pos)   { return !!(this.#bits[pos >> 3] & (1 << (pos & 7))); }

  // O(k)
  add(item) {
    for (const pos of this.#positions(item)) this.#setBit(pos);
  }

  // O(k) — returns false: definitely not present; true: probably present
  mightContain(item) {
    return this.#positions(item).every(pos => this.#testBit(pos));
  }

  get fillRatio() {
    let set = 0;
    for (const byte of this.#bits) {
      let b = byte;
      while (b) { set += b & 1; b >>= 1; }
    }
    return set / this.#m;
  }
}

const bf = new BloomFilter(2048, 7);
['apple','banana','cherry','date','elderberry'].forEach(w => bf.add(w));

console.log(bf.mightContain('apple'));     // true  (definitely)
console.log(bf.mightContain('cherry'));    // true  (definitely)
console.log(bf.mightContain('mango'));     // false (definitely not)
console.log(bf.mightContain('grape'));     // false (probably not)
console.log('fill ratio:', bf.fillRatio.toFixed(4)); // low fill = low FPR

// Bloom filter sizing formulas
// Given: n (expected insertions), p (target false-positive rate)
// Optimal m (bits): m = -n * ln(p) / (ln(2))^2
// Optimal k (hashes): k = (m/n) * ln(2)

function bloomFilterSize(n, targetFPR) {
  const ln2 = Math.LN2;
  const m   = Math.ceil(-n * Math.log(targetFPR) / (ln2 * ln2));
  const k   = Math.round((m / n) * ln2);
  return { bits: m, hashes: k, bytes: Math.ceil(m / 8) };
}

// Examples:
console.log(bloomFilterSize(1_000_000, 0.01));  // 1% FPR
// { bits: 9585059, hashes: 7, bytes: 1198133 } ≈ 1.1 MB for 1M items

console.log(bloomFilterSize(1_000_000, 0.001)); // 0.1% FPR
// { bits: 14377589, hashes: 10, bytes: 1797199 } ≈ 1.7 MB for 1M items

// Comparison: plain hash set for 1M items, avg 64-byte strings = 64 MB
// Bloom filter at 1% FPR = 1.1 MB — ~58× smaller, but probabilistic

// Bloom filter vs alternatives:
//
// Hash set:       O(1) exact,     O(n) space,  supports delete
// Bloom filter:   O(k) probabilistic, O(m) bits, NO delete (standard)
// Counting BF:    O(k) probabilistic, O(4m) bits, supports delete
// Cuckoo filter:  O(1) probabilistic, O(m) bits, supports delete

